        return condition({ steps });
      }))).some((condition) => condition);
      hasFinishedSteps = hasFinishedSteps || hasStopped;
    }
    if (rest.onIterationComplete && !typedInputData.backgroundTaskPending) {
      const isFinal = !typedInputData.stepResult?.isContinued || hasFinishedSteps, iterationContext = {
        iteration: accumulatedSteps.length,
        maxIterations: rest.maxSteps,
        text: typedInputData.output.text || "",
        toolCalls: (typedInputData.output.toolCalls || []).map((tc) => ({
          id: tc.toolCallId || tc.id || "",
          name: tc.toolName || tc.name || "",
          args: tc.args || {}
        })),
        toolResults: toolResultParts.map((tr) => ({
          id: tr.toolCallId,
          name: tr.toolName,
          result: unwrapToolResultOutput(tr.output)
        })),
        isFinal,
        finishReason: typedInputData.stepResult?.reason || "unknown",
        runId,
        threadId: readScoped(scopeCtx, THREAD_ID_KEY, "threadId"),
        resourceId: readScoped(scopeCtx, RESOURCE_ID_KEY, "resourceId"),
        agentId: rest.agentId,
        agentName: rest.agentName || rest.agentId,
        messages: messageList.get.all.db()
      };
      try {
        const iterationResult = await rest.onIterationComplete(iterationContext);
        if (iterationResult) {
          if (iterationResult.feedback && typedInputData.stepResult?.isContinued) {
            messageList.add({
              id: rest.mastra?.generateId() || globalThis.crypto.randomUUID(),
              createdAt: new Date,
              type: "text",
              role: "assistant",
              content: {
                parts: [{
                  type: "text",
                  text: iterationResult.feedback
                }],
                metadata: {
                  mode: "stream",
                  completionResult: { suppressFeedback: !0 }
                },
                format: 2
              }
            }, "response");
            if (iterationResult.continue === !1)
              pendingFeedbackStop = !0;
            else if (!hasFinishedSteps && rest.maxSteps && accumulatedSteps.length < rest.maxSteps) {
              hasFinishedSteps = !1;
              typedInputData.stepResult.isContinued = !0;
            }
          } else if (iterationResult.continue === !1 && !hasFinishedSteps)
            hasFinishedSteps = !0;
          else if (iterationResult.continue === !0 && (hasFinishedSteps || !typedInputData.stepResult?.isContinued)) {
            if (rest.maxSteps && accumulatedSteps.length < rest.maxSteps || !rest.maxSteps) {
              hasFinishedSteps = !1;
              if (typedInputData.stepResult)
                typedInputData.stepResult.isContinued = !0;
            }
          }
        }
      } catch (error) {
        rest.logger?.error("Error in onIterationComplete hook:", error);
      }
    }
    if (!hasFinishedSteps && readScoped(scopeCtx, DELEGATION_BAILED_KEY, "_delegationBailed")) {
      hasFinishedSteps = !0;
      writeScoped(scopeCtx, DELEGATION_BAILED_KEY, "_delegationBailed", !1);
    }
    if (typedInputData.stepResult)
      typedInputData.stepResult.isContinued = hasFinishedSteps ? !1 : typedInputData.stepResult.isContinued;
    const hasSteps = (typedInputData.output?.steps?.length ?? 0) > 0;
    if (typedInputData.stepResult?.reason !== "tripwire" || hasSteps)
      await outputWriter({
        type: "step-finish",
        runId,
        from: "AGENT",
        payload: typedInputData
      });
    if (typedInputData.stepResult?.reason === void 0)
      return !1;
    return typedInputData.stepResult?.isContinued ?? !1;
  }

